SELECT id, dept_id AS deptId, qybh, bh, short_name AS shortName, parent_id AS parentId, detail_address AS detailAddress, status, creator_id AS creatorId, create_time AS createTime, update_time AS updateTime, dept_id_path AS deptIdPath, dept_name_path AS deptNamePath FROM ve_bm_4849 WHERE qybh = #{dto.qybh}
AND dept_id = #{dto.deptId}
AND bh = #{dto.bh}
AND short_name LIKE #{nameLike}
AND parent_id = #{dto.parentId}
AND status = #{dto.status}
ORDER BY bh
